from __future__ import absolute_import
from itertools import chain

import yaml

from hran_file_operations.exceptions import MissingCellsMapContent


class CellsMapReader(object):
    """

    """

    def __init__(self):
        self.cells_dict = None

    def load_cellsmap(self, path):
        """
        Keyword for loading cellsmap from file with yaml format.

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** damian.skrzypczak@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | path               | Yes    | path of cellsmap                      |
        |                    |        | file with yaml extention              |
        +--------------------+--------+---------------------------------------+

        **Example:**

        .. code-block:: robotframework

           Load cellsmap path=path/to/cellsmap.yml
        """
        with open(path) as cellsmap_yaml:
            self.cells_dict = yaml.load(cellsmap_yaml)

    def cells_for_rmod(self, rmod_serial_number):
        """
        Keyword for getting cells connected to rmod with given serial number

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** damian.skrzypczak@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | For given radio module serial number, returning dictionary
        | with information about its connected cells,
        | grouped by direction parameter ("TX","RX")
        | and non-grouped ("ALL")

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | rmod_serial_number | Yes    | serial number of radio module which   |
        |                    |        | connected cells will be listed        |
        +--------------------+--------+---------------------------------------+

        **Example:**

        .. code-block:: robotframework

           Cells for rmod  rmod_serial_number=F7171600205
        """
        cells_for_rmod = {"TX": [],
                          "RX": [],
                          "ALL": set()}
        if self.cells_dict:
            for cell in list(self.cells_dict.values()):
                cell_data = self.rmods_for_cell(cell["dist_name"])
                for direction in "TX", "RX":
                    if rmod_serial_number in cell_data[direction]:
                        cells_for_rmod[direction].append(cell["dist_name"])
                        cells_for_rmod["ALL"].add(cell["dist_name"])
            return cells_for_rmod
        else:
            raise MissingCellsMapContent(
                'There is no loaded content of cellsmap, '
                'check if method "load_cellsmap" was previously called')

    def rmods_for_cell(self, cell_distname):
        """
        Keyword for getting radio modules connected to cell with given distname

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** damian.skrzypczak@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | For given cell distname, returning dictionary
        | with information about radio modules which its connected with,
        | grouped by direction parameter ("TX","RX")
        | and non-grouped ("ALL")

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | cell_distnames     | Yes    | distname of cell which connected      |
        |                    |        | radio modules will be listed          |
        +--------------------+--------+---------------------------------------+

        **Example:**

        .. code-block:: robotframework

           Rmods for cell
           ...  cell_distname=/path/to/LNCEL_R-XXXXX

        """
        rmods_for_cells = {}
        if self.cells_dict:
            for cell_data in list(self.cells_dict.values()):
                rmods_for_cells = self._extract_rmods_for_cell(
                    cell_data,
                    cell_distname,
                    rmods_for_cells)
            rmods_for_cells["ALL"] = set(chain(*list(rmods_for_cells.values())))
            return rmods_for_cells
        else:
            raise MissingCellsMapContent(
                'There is no loaded content of cellsmap, '
                'check if method "load_cellsmap" was previously called')

    def _extract_rmods_for_cell(self, cell_data, cell_distname,
                                rmods_for_cells):
        if cell_data["dist_name"] == cell_distname:
            rmods_for_cells = {
                "RX": [n["rmod"] for n in cell_data["RX"]],
                "TX": [n["rmod"] for n in cell_data["TX"]]}
        return rmods_for_cells
